require dirname(__DIR__).'/app/bootstrap.php';Auth::requireAdmin();$adminTitle='Manajemen Finalis';$eventId=(int)($_GET['event']??(active_event()['id']??0));$id=(int)($_GET['edit']??0);$edit=null;if($id){$s=db()->prepare('SELECT * FROM finalists WHERE id=?');$s->execute([$id]);$edit=$s->fetch();}
if(is_post()){try{verify_csrf();$action=(string)($_POST['action']??'save');if($action==='delete'){$fid=(int)$_POST['id'];db()->prepare('UPDATE finalists SET is_active=0,updated_at=NOW() WHERE id=?')->execute([$fid]);audit('DEACTIVATE_FINALIST','finalists',$fid);flash('success','Finalis dinonaktifkan.');redirect('admin/finalists.php?event='.(int)$_POST['event_id']);}$photo=save_upload('photo','finalists');$data=['event_id'=>(int)$_POST['event_id'],'category'=>$_POST['category'],'contestant_number'=>(int)$_POST['contestant_number'],'full_name'=>trim((string)$_POST['full_name']),'slug'=>slugify(trim((string)$_POST['full_name']).'-'.$_POST['category'].'-'.$_POST['contestant_number']),'region_id'=>(int)$_POST['region_id'],'biography'=>trim((string)$_POST['biography']),'motto'=>trim((string)$_POST['motto']),'education'=>trim((string)$_POST['education']),'program_description'=>trim((string)$_POST['program_description']),'instagram'=>trim((string)$_POST['instagram']),'is_featured'=>isset($_POST['is_featured'])?1:0,'is_active'=>isset($_POST['is_active'])?1:0];if($data['full_name']===''||$data['contestant_number']<1)throw new RuntimeException('Nama dan nomor finalis wajib diisi.');$fid=(int)($_POST['id']??0);if($fid){$old=db()->prepare('SELECT * FROM finalists WHERE id=?');$old->execute([$fid]);$old=$old->fetch();$sql='UPDATE finalists SET event_id=?,category=?,contestant_number=?,full_name=?,slug=?,region_id=?,biography=?,motto=?,education=?,program_description=?,instagram=?,is_featured=?,is_active=?'.($photo?',photo=?':'').',updated_at=NOW() WHERE id=?';$params=array_values($data);if($photo)$params[]=$photo;$params[]=$fid;db()->prepare($sql)->execute($params);audit('UPDATE_FINALIST','finalists',$fid,$old,$data);}else{$stmt=db()->prepare('INSERT INTO finalists(event_id,category,contestant_number,full_name,slug,region_id,photo,biography,motto,education,program_description,instagram,is_featured,is_active,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())');$stmt->execute([$data['event_id'],$data['category'],$data['contestant_number'],$data['full_name'],$data['slug'],$data['region_id'],$photo,$data['biography'],$data['motto'],$data['education'],$data['program_description'],$data['instagram'],$data['is_featured'],$data['is_active']]);$fid=(int)db()->lastInsertId();audit('CREATE_FINALIST','finalists',$fid,null,$data);}flash('success','Data finalis berhasil disimpan.');redirect('admin/finalists.php?event='.$data['event_id']);}catch(Throwable $e){flash('danger',$e->getMessage());}}
$events=db()->query('SELECT id,name,year FROM events ORDER BY year DESC')->fetchAll();$regions=db()->query('SELECT * FROM regions ORDER BY sort_order,name')->fetchAll();$stmt=db()->prepare("SELECT f.*,r.name region_name,COALESCE(pl.total_points,0) total_points FROM finalists f JOIN regions r ON r.id=f.region_id LEFT JOIN (SELECT event_id,finalist_id,SUM(points) total_points FROM point_ledgers GROUP BY event_id,finalist_id) pl ON pl.finalist_id=f.id AND pl.event_id=f.event_id WHERE f.event_id=? ORDER BY f.category,f.contestant_number");$stmt->execute([$eventId]);$rows=$stmt->fetchAll();require __DIR__.'/partials/header.php';
?>
<div class="d-flex flex-wrap justify-content-between gap-3 mb-4"><form><select class="form-select" name="event" onchange="this.form.submit()"><?php foreach($events as $ev):?><option value="<?= (int)$ev['id'] ?>" <?= $eventId===(int)$ev['id']?'selected':'' ?>><?= e($ev['year'].' - '.$ev['name']) ?></option><?php endforeach;?></select></form><button class="btn btn-admin rounded-pill px-4" data-bs-toggle="modal" data-bs-target="#formModal"><i class="bi bi-plus-lg me-2"></i>Tambah Finalis</button></div>
<div class="admin-card overflow-hidden"><div class="table-responsive"><table class="table table-admin"><thead><tr><th>Finalis</th><th>Kelompok</th><th>Asal</th><th>Poin</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><div class="d-flex align-items-center gap-3"><img class="admin-avatar" src="<?= upload_url($r['photo'],$r['category']==='DAYANG'?'images/placeholder-dayang.svg':'images/placeholder-bujang.svg') ?>"><div><strong><?= str_pad((string)$r['contestant_number'],2,'0',STR_PAD_LEFT) ?>. <?= e($r['full_name']) ?></strong><small class="d-block text-secondary"><?= e($r['education']) ?></small></div></div></td><td><span class="badge text-bg-light"><?= e($r['category']) ?></span></td><td><?= e($r['region_name']) ?></td><td class="fw-bold text-success"><?= number_format((int)$r['total_points'],0,',','.') ?></td><td><?= $r['is_active']?'<span class="text-success">Aktif</span>':'<span class="text-danger">Nonaktif</span>' ?></td><td class="text-end"><a class="btn btn-sm btn-outline-success" href="?event=<?= $eventId ?>&edit=<?= (int)$r['id'] ?>"><i class="bi bi-pencil"></i></a><form method="post" class="d-inline"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="event_id" value="<?= $eventId ?>"><button class="btn btn-sm btn-outline-danger" data-confirm="Nonaktifkan finalis ini?"><i class="bi bi-eye-slash"></i></button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="6" class="text-center py-5 text-secondary">Belum ada finalis pada event ini.</td></tr><?php endif;?></tbody></table></div></div>
<div class="modal fade <?= $edit?'show':'' ?>" id="formModal" tabindex="-1" <?= $edit?'style="display:block;background:rgba(0,0,0,.5)"':'' ?>><div class="modal-dialog modal-xl modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h5 class="modal-title"><?= $edit?'Edit Finalis':'Tambah Finalis' ?></h5><a href="finalists.php?event=<?= $eventId ?>" class="btn-close"></a></div><form method="post" enctype="multipart/form-data"><div class="modal-body p-4"><?= csrf_field() ?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><div class="row g-3"><div class="col-md-4"><label class="form-label">Event</label><select class="form-select" name="event_id"><?php foreach($events as $ev):?><option value="<?= (int)$ev['id'] ?>" <?= ($edit['event_id']??$eventId)==$ev['id']?'selected':'' ?>><?= e($ev['year'].' - '.$ev['name']) ?></option><?php endforeach;?></select></div><div class="col-md-4"><label class="form-label">Kelompok</label><select class="form-select" name="category"><option value="BUJANG" <?= ($edit['category']??'BUJANG')==='BUJANG'?'selected':'' ?>>Bujang</option><option value="DAYANG" <?= ($edit['category']??'')==='DAYANG'?'selected':'' ?>>Dayang</option></select></div><div class="col-md-4"><label class="form-label">Nomor Finalis</label><input class="form-control" type="number" name="contestant_number" required value="<?= e($edit['contestant_number']??1) ?>"></div><div class="col-md-8"><label class="form-label">Nama Lengkap</label><input class="form-control" name="full_name" required value="<?= e($edit['full_name']??'') ?>"></div><div class="col-md-4"><label class="form-label">Kabupaten/Kota</label><select class="form-select" name="region_id"><?php foreach($regions as $rg):?><option value="<?= (int)$rg['id'] ?>" <?= ($edit['region_id']??0)==$rg['id']?'selected':'' ?>><?= e($rg['name']) ?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Foto</label><input class="form-control" type="file" name="photo" accept="image/jpeg,image/png,image/webp"><small class="text-secondary">JPG/PNG/WEBP maksimal 5 MB, rasio 4:5.</small></div><div class="col-md-6"><label class="form-label">Pendidikan</label><input class="form-control" name="education" value="<?= e($edit['education']??'') ?>"></div><div class="col-12"><label class="form-label">Motto</label><input class="form-control" name="motto" value="<?= e($edit['motto']??'') ?>"></div><div class="col-12"><label class="form-label">Biografi</label><textarea class="form-control" rows="4" name="biography"><?= e($edit['biography']??'') ?></textarea></div><div class="col-12"><label class="form-label">Program/Gagasan</label><textarea class="form-control" rows="4" name="program_description"><?= e($edit['program_description']??'') ?></textarea></div><div class="col-md-8"><label class="form-label">URL Instagram</label><input class="form-control" type="url" name="instagram" value="<?= e($edit['instagram']??'') ?>"></div><div class="col-md-4 d-flex align-items-end gap-3 pb-2"><div class="form-check"><input class="form-check-input" type="checkbox" name="is_featured" <?= ($edit['is_featured']??0)?'checked':'' ?>><label class="form-check-label">Unggulan</label></div><div class="form-check"><input class="form-check-input" type="checkbox" name="is_active" <?= !isset($edit['is_active'])||$edit['is_active']?'checked':'' ?>><label class="form-check-label">Aktif</label></div></div></div></div><div class="modal-footer"><a href="finalists.php?event=<?= $eventId ?>" class="btn btn-light">Batal</a><button class="btn btn-admin">Simpan Finalis</button></div></form></div></div></div>
